// Monaco for the workbench: languages (Monarch tokenizers generated by editors/vscode/scripts/grammars.py), themes,
// one model per opened project file, and the language features answered by the plca language server.

import * as monaco from './monaco.ts';
import monarch from './generated/monarch.json';
import type { LspClient } from './lsp.ts';
import { type Finding, type Range, uriOf, pathOf } from './model.ts';

(self as any).MonacoEnvironment = {
  getWorker: () => new Worker('/assets/editor.worker.js', { name: 'editor' }),
};

export { monaco };

const ST_CONFIG: monaco.languages.LanguageConfiguration = {
  comments: { lineComment: '//', blockComment: ['(*', '*)'] },
  brackets: [
    ['(', ')'],
    ['[', ']'],
  ],
  autoClosingPairs: [
    { open: '(', close: ')' },
    { open: '[', close: ']' },
    { open: "'", close: "'", notIn: ['string', 'comment'] },
    { open: '"', close: '"', notIn: ['string', 'comment'] },
    { open: '(*', close: ' *)', notIn: ['string'] },
  ],
  wordPattern: /(-?\d*\.\d\w*)|([^`~!@#$%^&*()\-=+[{\]}\\|;:'",.<>/?\s]+)/g,
};

const XML_CONFIG: monaco.languages.LanguageConfiguration = {
  comments: { blockComment: ['<!--', '-->'] },
  brackets: [['<', '>']],
};

/** Language ids with plca features (definition, hover, …); plain XML/YAML only get colours or none. */
export const PLC_LANGUAGES = ['iec-st', 'siemens-scl', 'twincat-xml', 'rockwell-l5x', 'plcopen-xml'];

let registered = false;

export function registerLanguages(): void {
  if (registered) {
    return;
  }
  registered = true;
  const all = monarch as Record<string, any>;
  for (const id of Object.keys(all)) {
    monaco.languages.register({ id });
    monaco.languages.setMonarchTokensProvider(id, all[id]);
    monaco.languages.setLanguageConfiguration(id, id.endsWith('-xml') || id === 'rockwell-l5x' ? XML_CONFIG : ST_CONFIG);
  }
  for (const id of ['xml-plain', 'yaml-plain']) {
    monaco.languages.register({ id });
  }
  monaco.languages.setMonarchTokensProvider('xml-plain', all['twincat-xml']);
  defineThemes();
}

function defineThemes(): void {
  const rules = (dark: boolean): monaco.editor.ITokenThemeRule[] => [
    { token: 'comment', foreground: dark ? '7f9a86' : '4f7a57', fontStyle: 'italic' },
    { token: 'keyword', foreground: dark ? '8ab4e8' : '1f4f8a', fontStyle: 'bold' },
    { token: 'type', foreground: dark ? '7fc8c0' : '17736b' },
    { token: 'number', foreground: dark ? 'd8a65e' : '9a5b00' },
    { token: 'number.hex', foreground: dark ? 'd8a65e' : '9a5b00' },
    { token: 'string', foreground: dark ? 'c9a4d8' : '7a3b8f' },
    { token: 'string.escape', foreground: dark ? 'e0b8ee' : '5d2370' },
    { token: 'constant', foreground: dark ? 'd8a65e' : '9a5b00' },
    { token: 'metatag', foreground: dark ? '9aa7b0' : '6b7780' },
    { token: 'variable.predefined', foreground: dark ? 'f08a7e' : 'b02a1e' },
    { token: 'variable', foreground: dark ? 'dfe6ea' : '22313a' },
    { token: 'variable.parameter', foreground: dark ? 'b7c6cf' : '3d5563' },
    { token: 'tag', foreground: dark ? '8ab4e8' : '1f4f8a' },
    { token: 'attribute.name', foreground: dark ? '9fb7c4' : '4a6575' },
    { token: 'attribute.value', foreground: dark ? 'c9a4d8' : '7a3b8f' },
    { token: 'delimiter.cdata', foreground: dark ? '6f7f88' : '8a969d' },
    { token: 'operator', foreground: dark ? 'b7c6cf' : '3d5563' },
  ];
  monaco.editor.defineTheme('plca-light', {
    base: 'vs',
    inherit: true,
    rules: rules(false),
    colors: {
      'editor.background': '#fafbfb',
      'editor.lineHighlightBackground': '#eef2f4',
      'editorLineNumber.foreground': '#9aa6ad',
      'editorError.foreground': '#c62a1f',
      'editorWarning.foreground': '#c98500',
      'editorInfo.foreground': '#1f5fa6',
    },
  });
  monaco.editor.defineTheme('plca-dark', {
    base: 'vs-dark',
    inherit: true,
    rules: rules(true),
    colors: {
      'editor.background': '#1b2328',
      'editor.lineHighlightBackground': '#222c32',
      'editorLineNumber.foreground': '#5d6b73',
      'editorError.foreground': '#ef6a5f',
      'editorWarning.foreground': '#e8b23c',
      'editorInfo.foreground': '#6aa5e6',
    },
  });
}

export function themeName(): string {
  return matchMedia('(prefers-color-scheme: dark)').matches ? 'plca-dark' : 'plca-light';
}

// ---- conversions ---------------------------------------------------------------------------

export function toMonacoRange(r: Range): monaco.IRange {
  return {
    startLineNumber: r.start.line + 1,
    startColumn: r.start.character + 1,
    endLineNumber: r.end.line + 1,
    endColumn: r.end.character + 1,
  };
}

const MARKER: Record<string, monaco.MarkerSeverity> = {
  error: monaco.MarkerSeverity.Error,
  warning: monaco.MarkerSeverity.Warning,
  info: monaco.MarkerSeverity.Info,
  hint: monaco.MarkerSeverity.Hint,
};

export function setMarkers(model: monaco.editor.ITextModel, findings: Finding[], owner = 'plca'): void {
  monaco.editor.setModelMarkers(
    model,
    owner,
    findings.map((f) => ({
      ...toMonacoRange(f.range),
      severity: MARKER[f.severity],
      message: f.message,
      code: f.rule,
      source: 'plca',
    })),
  );
}

// ---- language features ---------------------------------------------------------------------

/** The project file a model shows, or null for diff and scratch models. */
export function pathOfModel(model: monaco.editor.ITextModel): string | null {
  return model.uri.scheme === 'plca-project' ? decodeURIComponent(model.uri.path.slice(1)) : null;
}

export function modelUri(path: string): monaco.Uri {
  return monaco.Uri.from({ scheme: 'plca-project', path: '/' + encodeURIComponent(path) });
}

interface LspLocation {
  uri: string;
  range: Range;
}

/**
 * Registers definition, references, hover and outline for the PLC languages, answered by {@code lsp()} (the current
 * project's server). {@code ensureModel} loads a file other than the open one (a definition elsewhere);
 * {@code open} shows a file at a position (Monaco's editor opener).
 */
export function registerFeatures(
  lsp: () => LspClient | null,
  ensureModel: (path: string) => Promise<monaco.editor.ITextModel | null>,
  open: (path: string, range: Range | null) => void,
): void {
  const at = (model: monaco.editor.ITextModel, position: monaco.Position) => {
    const path = pathOfModel(model);
    return path === null
      ? null
      : { textDocument: { uri: uriOf(path) }, position: { line: position.lineNumber - 1, character: position.column - 1 } };
  };
  const locations = async (list: LspLocation[] | null): Promise<monaco.languages.Location[]> => {
    const out: monaco.languages.Location[] = [];
    for (const l of list ?? []) {
      const path = pathOf(l.uri);
      const model = path === null ? null : await ensureModel(path);
      if (model) {
        out.push({ uri: model.uri, range: toMonacoRange(l.range) });
      }
    }
    return out;
  };
  for (const language of PLC_LANGUAGES) {
    monaco.languages.registerDefinitionProvider(language, {
      async provideDefinition(model, position) {
        const p = at(model, position);
        const c = lsp();
        return p && c ? locations(await c.request<LspLocation[]>('textDocument/definition', p)) : [];
      },
    });
    monaco.languages.registerReferenceProvider(language, {
      async provideReferences(model, position, context) {
        const p = at(model, position);
        const c = lsp();
        return p && c
          ? locations(
              await c.request<LspLocation[]>('textDocument/references', {
                ...p,
                context: { includeDeclaration: context.includeDeclaration },
              }),
            )
          : [];
      },
    });
    monaco.languages.registerHoverProvider(language, {
      async provideHover(model, position) {
        const p = at(model, position);
        const c = lsp();
        if (!p || !c) {
          return null;
        }
        const h = await c.request<{ contents: { value: string } | string; range?: Range } | null>('textDocument/hover', p);
        if (!h) {
          return null;
        }
        const value = typeof h.contents === 'string' ? h.contents : h.contents.value;
        return {
          contents: [{ value, isTrusted: false, supportHtml: false }],
          range: h.range ? toMonacoRange(h.range) : undefined,
        };
      },
    });
    monaco.languages.registerDocumentSymbolProvider(language, {
      async provideDocumentSymbols(model) {
        const path = pathOfModel(model);
        const c = lsp();
        if (path === null || !c) {
          return [];
        }
        const symbols = await c.request<any[]>('textDocument/documentSymbol', { textDocument: { uri: uriOf(path) } });
        const conv = (s: any): monaco.languages.DocumentSymbol => ({
          name: s.name,
          detail: s.detail ?? '',
          kind: (s.kind ?? 13) - 1, // LSP SymbolKind is 1-based, Monaco's 0-based
          tags: [],
          range: toMonacoRange(s.range),
          selectionRange: toMonacoRange(s.selectionRange),
          children: (s.children ?? []).map(conv),
        });
        return (symbols ?? []).map(conv);
      },
    });
  }
  monaco.editor.registerEditorOpener({
    openCodeEditor(_source, resource, selection) {
      if (resource.scheme !== 'plca-project') {
        return false;
      }
      const path = decodeURIComponent(resource.path.slice(1));
      let range: Range | null = null;
      if (selection && 'startLineNumber' in selection) {
        range = {
          start: { line: selection.startLineNumber - 1, character: selection.startColumn - 1 },
          end: { line: selection.endLineNumber - 1, character: selection.endColumn - 1 },
        };
      } else if (selection && 'lineNumber' in selection) {
        const pos = { line: selection.lineNumber - 1, character: selection.column - 1 };
        range = { start: pos, end: pos };
      }
      open(path, range);
      return true;
    },
  });
}
